            prefix[..paren_idx].to_string()
        } else {
            prefix.to_string()
        };

        // Map commit type to section
        let section = match type_name.as_str() {
            "feat" => "Features",
            "fix" => "Bug Fixes",
            "docs" => "Documentation",
            "perf" => "Performance",
            "refactor" => "Code Refactoring",
            "test" => "Tests",
            "chore" => "Chores",
            "style" => "Style",
            "ci" => "CI",
