fn get_date() -> String {
    use std::time::{SystemTime, UNIX_EPOCH};

    let duration = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default();

    // Simple date formatting (YYYY-MM-DD)
    let seconds = duration.as_secs();
    let days_since_epoch = seconds / 86400;

    // Year 1970 started on a Thursday
    let mut year = 1970;
    let mut days_left = days_since_epoch as i32;

    loop {
        let days_in_year = if is_leap_year(year) { 366 } else { 365 };
        if days_left < days_in_year {
            break;
        }
        days_left -= days_in_year;
        year += 1;
    }

    let mut month = 1;
    let mut day = days_left + 1;

    let days_per_month = get_days_per_month(year);
    for (i, &days) in days_per_month.iter().enumerate() {
        if day <= days {
            month = i as i32 + 1;
            break;
        }
        day -= days;
    }

    format!("{:04}-{:02}-{:02}", year, month, day)
}

fn is_leap_year(year: i32) -> bool {
    (year % 4 == 0 && year % 100 != 0) || year % 400 == 0
}

fn get_days_per_month(year: i32) -> [i32; 12] {
    if is_leap_year(year) {
        [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    } else {
        [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    }
}

fn generate_markdown_output(version: &Option<String>, date: &str, sections: &HashMap<String, Vec<String>>) -> String {
    let mut output = String::new();

    // Header
    output.push_str("<a name=\"");
    if let Some(v) = version {
        output.push_str(v);
    }
    output.push_str("\"></a>\n");

    output.push_str("## ");
    if let Some(v) = version {
        output.push_str(v);
    }
    output.push_str("  (");
    output.push_str(date);
    output.push_str(")\n\n");

    Ok(())
}

fn generate_json_output(version: &Option<String>, date: &str, sections: &HashMap<String, Vec<String>>) -> String {
    let mut output = String::from("{\"header\":{\"version\":");

    if let Some(v) = version {
        output.push_str("Some(\"");
        output.push_str(v);
        output.push_str("\")");
    } else {
        output.push_str("None");
    }

    output.push_str(",\"patch_version\":false,\"subtitle\":null,\"date\":\"");
    output.push_str(date);
    output.push_str("\"},\"sections\":null}");

    output
}
