    let commit_hashes = String::from_utf8_lossy(&output.stdout);
    let mut commits = Vec::new();

    for hash in commit_hashes.lines() {
        let hash = hash.trim();
        if !hash.is_empty() {
            if let Ok(msg) = get_commit_message(work_tree, git_dir, hash) {
                commits.push(msg);
            }
        }
    }

    Ok(commits)
