        .arg("describe")
        .arg("--tags")
        .arg("--abbrev=0")
        .output()
        .map_err(|_| "Failed to run git describe".to_string())?;

    if output.status.success() {
        let tag = String::from_utf8_lossy(&output.stdout).trim().to_string();
