  -p, --patch             Increment patch version by one
  -s, --subtitle <STR>    
  -t, --to <COMMIT>       e.g. 8057684 [default: HEAD]
  -o, --outfile <PATH>    Where to write the changelog (Defaults to stdout when omitted)
  -c, --config <COMMIT>   The Clog Configuration TOML file to use [default: .clog.toml]
  -i, --infile <PATH>     A changelog to append to, but *NOT* write to (Useful in conjunction with
                          --outfile)
      --setversion <VER>  e.g. 1.0.1
  -F, --from-latest-tag   use latest tag as start (instead of --from)
  -l, --link-style <STR>  The style of repository link to generate [default: github] [possible
                          values: github, gitlab, stash, cgit]
  -C, --changelog <PATH>  A previous changelog to prepend new changes to (this is like using the
                          same file for both --infile and --outfile and should not be used in
                          conjunction with either)
  -h, --help              Print help
  -V, --version           Print version


If your .git directory is a child of your project directory (most common, such as /myproject/.git)
AND not in the current working directory (i.e you need to use --work-tree or --git-dir) you only
need to specify either the --work-tree (i.e. /myproject) OR --git-dir (i.e. /myproject/.git), you
don't need to use both.

If using the --config to specify a clog configuration TOML file NOT in the current working directory
(meaning you need to use --work-tree or --git-dir) AND the TOML file is inside your project
directory (i.e. /myproject/.clog.toml) you do not need to use --work-tree or --git-dir."#;
    println!("{}", help);
}

fn print_version() {
    println!("clog 0.10.0");
}

fn main() {
    let start = std::time::Instant::now();
    let (args, show_help, show_version) = parse_args();

    if show_help {
        print_help();
        return;
    }

    if show_version {
        print_version();
        return;
    }

    if let Err(e) = run(args, start) {
        eprintln!("\x1b[1;31merror:\x1b[0m {}", e);
        std::process::exit(1);
    }
}

fn run(args: Args, start: std::time::Instant) -> Result<(), String> {
    // Load config
    let config_path = &args.config;
    let config = load_config(config_path)?;

    // Determine repository
    let _repository = args.repository.clone()
        .or_else(|| config.get("repository").cloned())
        .unwrap_or_default();

    // Determine git directory
    let work_tree = args.work_tree.clone()
        .unwrap_or_else(|| PathBuf::from("."));

    let git_dir = args.git_dir.clone()
        .unwrap_or_else(|| work_tree.join(".git"));

    // Get commits
    let from = if args.from_latest_tag {
        get_latest_tag(&work_tree, &git_dir)?
    } else {
        args.from.clone()
    };

    let commits = if let Some(from_ref) = from {
        get_commits(&work_tree, &git_dir, &from_ref, &args.to)?
    } else {
        get_commits_all(&work_tree, &git_dir, &args.to)?
    };

    // Parse commits
    let mut _sections: HashMap<String, Vec<String>> = HashMap::new();
    for commit in commits {
        if let Some((section, message)) = parse_commit(&commit) {
            _sections.entry(section).or_insert_with(Vec::new).push(message);
        }
    }

    // Get date
    let date = get_date();

    // Generate output
    let output = if args.format == "json" {
        generate_json_output(&args.setversion, &date)
    } else {
        generate_markdown_output(&args.setversion, &date)
    };

    // Write output
    if let Some(outfile) = &args.outfile {
        fs::write(outfile, &output)
            .map_err(|_| "fatal I/O error with output file".to_string())?;
    } else {
        print!("{}", output);
    }

    let elapsed = start.elapsed().as_millis();
    println!("changelog written. (took {} ms)", elapsed);

    Ok(())
}

fn load_config(path: &str) -> Result<HashMap<String, String>, String> {
    let mut config = HashMap::new();

    if Path::new(path).exists() {
        let content = fs::read_to_string(path)
            .map_err(|_| "Failed to read config file".to_string())?;

        for line in content.lines() {
            let line = line.trim();
            if line.starts_with("repository") && line.contains('=') {
                if let Some(value) = line.split('=').nth(1) {
                    let value = value.trim().trim_matches('"');
                    config.insert("repository".to_string(), value.to_string());
                }
            } else if line.starts_with("from-latest-tag") && line.contains('=') {
                if let Some(value) = line.split('=').nth(1) {
                    config.insert("from-latest-tag".to_string(), value.trim().to_string());
                }
            }
        }
    }

    Ok(config)
}

fn get_latest_tag(work_tree: &Path, git_dir: &Path) -> Result<Option<String>, String> {
    let output = Command::new("git")
        .arg("--git-dir").arg(git_dir)
        .arg("--work-tree").arg(work_tree)
        .arg("describe")
        .arg("--tags")
        .arg("--abbrev=0")
        .output()
        .map_err(|_| "Failed to run git describe".to_string())?;

    if output.status.success() {
        let tag = String::from_utf8_lossy(&output.stdout).trim().to_string();
        Ok(Some(tag))
    } else {
        Ok(None)
    }
}

fn get_commits(work_tree: &Path, git_dir: &Path, from: &str, to: &str) -> Result<Vec<String>, String> {
    let range = format!("{}..{}", from, to);
    let output = Command::new("git")
        .arg("--git-dir").arg(git_dir)
        .arg("--work-tree").arg(work_tree)
        .arg("rev-list")
        .arg("--reverse")
        .arg(&range)
        .output()
        .map_err(|_| "Failed to run git rev-list".to_string())?;

    if !output.status.success() {
        return Ok(Vec::new());
    }

    let commit_hashes = String::from_utf8_lossy(&output.stdout);
    let mut commits = Vec::new();

    for hash in commit_hashes.lines() {
        let hash = hash.trim();
        if !hash.is_empty() {
            if let Ok(msg) = get_commit_message(work_tree, git_dir, hash) {
                commits.push(msg);
            }
        }
    }

    Ok(commits)
}

fn get_commits_all(work_tree: &Path, git_dir: &Path, to: &str) -> Result<Vec<String>, String> {
    let output = Command::new("git")
        .arg("--git-dir").arg(git_dir)
        .arg("--work-tree").arg(work_tree)
        .arg("rev-list")
        .arg("--reverse")
        .arg(to)
        .output()
        .map_err(|_| "Failed to run git rev-list".to_string())?;

    if !output.status.success() {
        return Ok(Vec::new());
    }

    let commit_hashes = String::from_utf8_lossy(&output.stdout);
    let mut commits = Vec::new();

    for hash in commit_hashes.lines() {
        let hash = hash.trim();
        if !hash.is_empty() {
            if let Ok(msg) = get_commit_message(work_tree, git_dir, hash) {
                commits.push(msg);
            }
        }
    }

    Ok(commits)
}

fn get_commit_message(work_tree: &Path, git_dir: &Path, hash: &str) -> Result<String, String> {
    let output = Command::new("git")
        .arg("--git-dir").arg(git_dir)
        .arg("--work-tree").arg(work_tree)
        .arg("log")
        .arg("-1")
        .arg("--format=%B")
        .arg(hash)
        .output()
        .map_err(|_| "Failed to get commit message".to_string())?;

    Ok(String::from_utf8_lossy(&output.stdout).trim().to_string())
}

fn parse_commit(commit: &str) -> Option<(String, String)> {
    let lines: Vec<&str> = commit.lines().collect();
    if lines.is_empty() {
        return None;
    }

    let first_line = lines[0];

    // Parse conventional commit format: type(scope): message
    if let Some((prefix, message)) = first_line.split_once(':') {
        let prefix = prefix.trim();

        // Extract type and scope
        let type_name = if let Some(paren_idx) = prefix.find('(') {
            prefix[..paren_idx].to_string()
        } else {
            prefix.to_string()
        };

        // Map commit type to section
        let section = match type_name.as_str() {
            "feat" => "Features",
            "fix" => "Bug Fixes",
            "docs" => "Documentation",
            "perf" => "Performance",
            "refactor" => "Code Refactoring",
            "test" => "Tests",
            "chore" => "Chores",
            "style" => "Style",
            "ci" => "CI",
            _ => return None,
        };

        let message = message.trim().to_string();
        Some((section.to_string(), message))
    } else {
        None
    }
}

fn get_date() -> String {
    use std::time::{SystemTime, UNIX_EPOCH};

    let duration = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default();

    // Simple date formatting (YYYY-MM-DD)
    let seconds = duration.as_secs();
    let days_since_epoch = seconds / 86400;

    // Year 1970 started on a Thursday
    let mut year = 1970;
    let mut days_left = days_since_epoch as i32;

    loop {
        let days_in_year = if is_leap_year(year) { 366 } else { 365 };
        if days_left < days_in_year {
            break;
        }
        days_left -= days_in_year;
        year += 1;
    }

    let mut month = 1;
    let mut day = days_left + 1;

    let days_per_month = get_days_per_month(year);
    for (i, &days) in days_per_month.iter().enumerate() {
        if day <= days {
            month = i as i32 + 1;
            break;
        }
        day -= days;
    }

    format!("{:04}-{:02}-{:02}", year, month, day)
}

fn is_leap_year(year: i32) -> bool {
    (year % 4 == 0 && year % 100 != 0) || year % 400 == 0
}

fn get_days_per_month(year: i32) -> [i32; 12] {
    if is_leap_year(year) {
        [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    } else {
        [31, 28, 31, 30, 31, 31, 30, 31, 30, 31, 30, 31]
    }
}

fn generate_markdown_output(version: &Option<String>, date: &str) -> String {
    let mut output = String::new();

    // Header
    output.push_str("<a name=\"");
    if let Some(v) = version {
        output.push_str(v);
    }
    output.push_str("\"></a>\n");

    output.push_str("## ");
    if let Some(v) = version {
        output.push_str(v);
    }
    output.push_str("  (");
    output.push_str(date);
    output.push_str(")\n\n");

    output
}

fn generate_json_output(version: &Option<String>, date: &str) -> String {
    let mut output = String::from("{\"header\":{\"version\":");

    if let Some(v) = version {
        output.push_str("Some(\"");
        output.push_str(v);
        output.push_str("\")");
    } else {
        output.push_str("None");
    }

    output.push_str(",\"patch_version\":false,\"subtitle\":null,\"date\":\"");
    output.push_str(date);
    output.push_str("\"},\"sections\":null}");

    output
}
